import csv
import io
import re


def parse_csv(raw_csv: str):
    expected_width = 4
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = [row for row in reader if row and any(cell.strip() for cell in row)]
    if not records:
        return {"columns": [], "rows": []}

    number_pattern = re.compile(
        r"^[+-]?(?:\d+(?:[.,]\d*)?|[.,]\d+)(?:[eE][+-]?\d+)?$"
    )

    def looks_numeric(value):
        return bool(number_pattern.match(value.strip()))

    # Prefer a textual row immediately preceding data as the header, so that
    # leading metadata or other preamble records are not mistaken for it.
    candidates = []
    for index, row in enumerate(records):
        if len(row) < 2 or looks_numeric(row[0]) or not row[0].strip():
            continue
        distance = None
        for next_index in range(index + 1, min(len(records), index + 6)):
            if looks_numeric(records[next_index][0]):
                distance = next_index - index
                break
        if distance is not None:
            candidates.append((distance, index))

    if candidates:
        _, header_index = min(candidates)
    else:
        header_index = next(
            (i for i, row in enumerate(records) if len(row) == expected_width),
            0,
        )

    columns = [cell.strip() for cell in records[header_index]]
    width = max(expected_width, len(columns))
    while len(columns) < width:
        columns.append(f"column_{len(columns) + 1}")

    rows = []
    for record in records[header_index + 1:]:
        if len(record) > width:
            for column_index in range(width, len(record)):
                columns.append(f"column_{column_index + 1}")
            width = len(record)
            for existing_row in rows:
                existing_row.extend([""] * (width - len(existing_row)))
        rows.append(record[:width] + [""] * max(0, width - len(record)))

    return {"columns": columns, "rows": rows}
